#requires -version 5.1
$ErrorActionPreference='Stop'
$projectRoot=Split-Path $PSScriptRoot -Parent
Set-Location -LiteralPath $projectRoot
Import-Module (Join-Path $projectRoot 'app\CleanData\Review.psm1') -Force
Import-Module (Join-Path $projectRoot 'app\CleanData\MemoryClear.Disk.psm1')
$results=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Condition,[string]$Message='Assertion failed');if(-not$Condition){throw $Message}}
function Check {param([string]$Name,[scriptblock]$Test);try{&$Test;$results.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$results.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}}
function Reject {param([scriptblock]$Action);$failed=$false;try{&$Action|Out-Null}catch{$failed=$true};Assert $failed 'Expected rejection'}
$root=Join-Path $projectRoot ('artifacts\disk-fixture-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root|Out-Null
[IO.File]::WriteAllText((Join-Path $root '.memoryclear-fixture'),'Readonly review fixtures')
foreach($name in @('safe.bin','danger.db','blocked.bin','review.log')){[IO.File]::WriteAllText((Join-Path $root $name),'Keep this test-owned file intact')}
$scan=Get-MCDiskScan -FixtureRoots @($root);$rows=@($scan.Rows|Where-Object{$_.Name-ne'.memoryclear-fixture'});$risks=@{};foreach($row in $rows){$risks[$row.Identity]=switch($row.Name){'safe.bin'{'Safe'}'danger.db'{'Danger'}'review.log'{'Review'}default{'Blocked'}}}
function Session {param([object[]]$Items=$rows);New-MCDiskReviewSession $scan $Items 'scope-A' -FixtureRisks $risks}
$required=@($rows|Where-Object{$_.Name-in@('danger.db','review.log')}|ForEach-Object{$_.Identity})
Check 'Review policy is bounded preview only' {$p=Get-MCDiskReviewPolicy;Assert (-not$p.executionEnabled-and$p.maximumItems-eq100-and$p.ttlSeconds-eq600)}
Check 'User rows remain blocked regardless of their proposed risk label' {$r=New-MCDiskReviewSession $scan $rows 'scope-A';try{Assert ($r.EligibleCount-eq0-and$r.BlockedCount-eq4-and-not$r.ExecutionEnabled);$r=Move-MCDiskReviewNext $r.SessionId 'scope-A';Assert ($r.Stage-eq'Blocked');Reject {Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true -Phrase $r.Phrase}}finally{Close-MCDiskReview $r.SessionId}}
Check 'Risky items cannot reach final step until each is reviewed' {$r=Session;try{Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A'};Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A' @($required[0])};$r=Move-MCDiskReviewNext $r.SessionId 'scope-A' $required;Assert ($r.Stage-eq'Confirm')}finally{Close-MCDiskReview $r.SessionId}}
Check 'Danger requires final acknowledgment plus exact session-specific phrase, without execution' {$r=Session;try{Reject {Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true -Phrase $r.Phrase};Move-MCDiskReviewNext $r.SessionId 'scope-A' $required|Out-Null;Reject {Confirm-MCDiskReview $r.SessionId 'scope-A' -Phrase $r.Phrase};Reject {Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true -Phrase 'XAC NHAN WRONG'};$r=Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true -Phrase $r.Phrase;Assert ($r.Stage-eq'PreviewApproved'-and$r.DeletedBytes-eq0-and-not$r.ExecutionEnabled);Reject {Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true -Phrase $r.Phrase}}finally{Close-MCDiskReview $r.SessionId}}
Check 'Safe-only fixture needs no risk acknowledgment or final confirmation step' {$r=Session @($rows|Where-Object{$_.Name-eq'safe.bin'});try{$r=Move-MCDiskReviewNext $r.SessionId 'scope-A';Assert ($r.Stage-eq'PreviewApproved'-and-not$r.ExecutionEnabled)}finally{Close-MCDiskReview $r.SessionId}}
Check 'Review-only fixture needs final acknowledgment but no danger phrase' {$r=Session @($rows|Where-Object{$_.Name-eq'review.log'});try{Move-MCDiskReviewNext $r.SessionId 'scope-A' @($r.Items[0].Id)|Out-Null;$r=Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true;Assert ($r.Stage-eq'PreviewApproved')}finally{Close-MCDiskReview $r.SessionId}}
Check 'Blocked items excluded from totals and cannot be passed as reviewed items' {$r=Session;try{$expected=0L;foreach($row in $rows){if($row.Name-ne'blocked.bin'){$expected+=$row.Snapshot.AllocatedBytes}};Assert ($r.AllocatedBytes-eq$expected-and$r.BlockedCount-eq1);Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A' @($rows.Identity)}}finally{Close-MCDiskReview $r.SessionId}}
Check 'Review state is detached from returned view objects' {$r=Session;try{$r.Items[0].Risk='Safe';$r.Items[0].Snapshot.LogicalBytes=0;$fresh=Get-MCDiskReviewState $r.SessionId;Assert ($fresh.Items[0].Snapshot.LogicalBytes-gt0);Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A'}}finally{Close-MCDiskReview $r.SessionId}}
Check 'Changing scope invalidates all prior approvals and cannot be reset to valid' {$r=Session;try{Move-MCDiskReviewNext $r.SessionId 'scope-A' $required|Out-Null;Reject {Confirm-MCDiskReview $r.SessionId 'scope-B' -Acknowledge $true -Phrase $r.Phrase};Assert ((Get-MCDiskReviewState $r.SessionId).Stage-eq'Invalidated');Reset-MCDiskReview $r.SessionId;Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A' $required}}finally{Close-MCDiskReview $r.SessionId}}
Check 'Expired or changed policy binding invalidates session' {foreach($kind in @('expiry','policy')){$r=Session;try{& (Get-Module Review) {param($id,$kind);if($kind-eq'expiry'){$script:Sessions[$id].Expires=[DateTime]::UtcNow.AddSeconds(-1)}else{$script:Sessions[$id].Policy='mismatch'}} $r.SessionId $kind;Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A' $required};Assert ((Get-MCDiskReviewState $r.SessionId).Stage-eq'Invalidated')}finally{Close-MCDiskReview $r.SessionId}}}
Check 'Back clears per-item approval; cancellation cannot be revived' {$r=Session;try{Move-MCDiskReviewNext $r.SessionId 'scope-A' $required|Out-Null;Reset-MCDiskReview $r.SessionId;Reject {Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true -Phrase $r.Phrase};Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A'};Reset-MCDiskReview $r.SessionId -Cancel;Reject {Move-MCDiskReviewNext $r.SessionId 'scope-A' $required}}finally{Close-MCDiskReview $r.SessionId}}
Check 'Duplicate selection and fixture risks on non-fixture scan are refused' {Reject {New-MCDiskReviewSession $scan @($rows[0],$rows[0]) 'scope-A' -FixtureRisks $risks};$copy=$scan.PSObject.Copy();$copy.Fixture=$false;Reject {New-MCDiskReviewSession $copy $rows 'scope-A' -FixtureRisks $risks}}
Check 'Closing session destroys approval state' {$r=Session;Close-MCDiskReview $r.SessionId;Reject {Get-MCDiskReviewState $r.SessionId}}
Check 'Native file content change between steps invalidates review and preserves file' {$r=Session;try{Move-MCDiskReviewNext $r.SessionId 'scope-A' $required|Out-Null;[IO.File]::AppendAllText((Join-Path $root 'danger.db'),'Changed fixture');Reject {Confirm-MCDiskReview $r.SessionId 'scope-A' -Acknowledge $true -Phrase $r.Phrase};Assert ((Get-MCDiskReviewState $r.SessionId).Stage-eq'Invalidated');Assert (Test-Path (Join-Path $root 'danger.db'))}finally{Close-MCDiskReview $r.SessionId}}
Check 'All selected fixture files still exist, review module has no executor import' {foreach($row in $rows){Assert (Test-Path -LiteralPath $row.Path)};$source=Get-Content (Join-Path $projectRoot 'app\CleanData\Review.psm1') -Raw;Assert ($source-notmatch'Import-Module[^\r\n]*FixtureExecutor'-and$source-notmatch'Invoke-MCDiskFixturePlan|DeleteFixture\(')}
$report=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Passed=@($results|Where-Object{$_.Passed}).Count;Failed=@($results|Where-Object{-not$_.Passed}).Count;Results=$results.ToArray();Scope='Readonly in-memory review sessions and native marked fixtures; no deletion or user-data access';Unverified=@('Production risk/authority and cleanup integration','Windows10/11 UI keyboard/DPI/operator acceptance')}
$report|ConvertTo-Json -Depth 6|Set-Content (Join-Path $projectRoot 'docs\verification\disk-review-tests.json') -Encoding UTF8
$results|Format-Table -AutoSize|Out-String|Write-Output
if($report.Failed){$results|Where-Object{-not$_.Passed}|Format-List|Out-String|Write-Output;exit 1}
